  { id: "configured", label: "Configured" },
  { id: "unset", label: "No URL yet" },
  { id: "read-only", label: "Read only" },
  { id: "loading", label: "Loading" },
  { id: "error", label: "Error" },
];

export default function WebhookEventsPage() {
